import {LESSONS,NOTES} from './content.js';
export const STORAGE_KEY='recorder-quest-v1';
export function fresh(){return {version:1,records:{},notes:{},composition:[],compositionTitle:'わたしのメロディー',settings:{tempo:72,names:true},last:null};}
export function parseNotes(sequence){return sequence.trim().split(/\s+/).filter(Boolean).map(t=>{const [note,d='1']=t.split(':');const beats=Number(d);if((note!=='R'&&!NOTES[note])||![.25,.5,1,1.5,2,3,4].includes(beats))throw Error('音のデータが正しくありません');return {note,beats};});}
export function points(s){return Object.values(s.records).reduce((n,r)=>n+(r.best||r.rating)*10,0);}
export function completed(s){return LESSONS.filter(l=>(s.records[l.id]?.rating||0)>=2).length;}
export function recommend(s){const last=LESSONS.find(l=>l.id===s.last);if(last&&s.records[last.id]?.rating===1){return {lesson:LESSONS.find(l=>l.id===last.prereq)||last,reason:'「むずかしい」のひとつ前を、ゆっくりおさらいしよう。'};}const l=LESSONS.find(l=>(s.records[l.id]?.rating||0)<2);return {lesson:l||LESSONS[0],reason:l?'今の「できた」の先にある、小さな一歩。':'全コースに挑戦したね。最初の音の変化を聴いてみよう。'};}
export function record(s,id,rating,reflection){if(!LESSONS.some(l=>l.id===id)||![1,2,3].includes(rating))throw Error('記録を確認してください');const old=s.records[id];s.records[id]={rating,best:Math.max(old?.best||old?.rating||0,rating),reflection:String(reflection||'').slice(0,800),date:new Date().toISOString(),attempts:(old?.attempts||0)+1};s.last=id;return s;}
export function validateBackup(data){if(!data||data.version!==1||typeof data.records!=='object'||!data.records||Array.isArray(data.records))throw Error('このサイトのバックアップを選んでね');const s=fresh();for(const [id,r]of Object.entries(data.records)){if(!LESSONS.some(l=>l.id===id)||!r||![1,2,3].includes(r.rating)||typeof r.reflection!=='string'||r.reflection.length>800||typeof r.date!=='string'||isNaN(Date.parse(r.date)))throw Error('学習記録の形式が違います');s.records[id]={rating:r.rating,best:[1,2,3].includes(r.best)?Math.max(r.best,r.rating):r.rating,reflection:r.reflection,date:r.date,attempts:Number.isInteger(r.attempts)&&r.attempts>0?Math.min(r.attempts,100000):1};}if(data.notes&&typeof data.notes==='object'&&!Array.isArray(data.notes)){for(const[id,n]of Object.entries(data.notes)){if(LESSONS.some(l=>l.id===id)&&typeof n==='string'&&n.length<=1600)s.notes[id]=n;}}
if(data.composition!==undefined){if(!Array.isArray(data.composition)||data.composition.length>32)throw Error('曲のデータが大きすぎます');s.composition=data.composition.map(n=>{if(!n||!(n.note==='R'||NOTES[n.note])||![.25,.5,1,1.5,2,3,4].includes(n.beats))throw Error('曲の音を確認してください');return {note:n.note,beats:n.beats};});}if(typeof data.compositionTitle==='string')s.compositionTitle=data.compositionTitle.slice(0,60);if(data.settings){s.settings.tempo=Number.isFinite(data.settings.tempo)?Math.max(40,Math.min(140,data.settings.tempo)):72;s.settings.names=data.settings.names!==false;}if(LESSONS.some(l=>l.id===data.last))s.last=data.last;return s;}
